// Generated by scripts/video/make-story.sh (src/gen/data.json): the story script and timeline
// (video/story.json), word timings of the voice lines, footage metadata and the end-card links.
import data from "./gen/data.json";

export type Rect = { x: number; y: number; width: number; height: number };
type Line = { id: string; text: string; at: number };
type Word = { w: string; s: number; e: number };
type Take = { file: string; seconds: number; width: number; height: number; marks: Record<string, number>; rects: Record<string, Rect> };

export const FPS: number = data.story.timeline.fps;
export const END: number = data.story.timeline.end;
export const LINES: Line[] = data.story.lines;
export const WORDS: Record<string, { words: Word[] | null }> = data.words as never;
export const SECTIONS: Record<string, number> = Object.fromEntries(data.story.timeline.sections as [string, number][]);
export const HITS: Record<string, number> = data.story.timeline.hits;
export const TAKES: Record<string, Take> = data.footage as never;
export const CONFIG: { builtBy: string; demoUrl: string; repoUrl: string } = data.config;

export const f = (s: number) => Math.round(s * FPS);
export const line = (id: string) => LINES.find((l) => l.id === id)!;
/** Absolute time (s) a word of a voice line starts: the index-th word, or the first word matching. */
export const wordAt = (id: string, which: number | string) => {
  const l = line(id);
  const ws = WORDS[id]?.words ?? [];
  const w = typeof which === "number" ? ws[which] : ws.find((x) => x.w.toLowerCase().replace(/[^a-z']/g, "").startsWith(which.toLowerCase()));
  return l.at + (w ? w.s : 0);
};
